def normalizar_unidades(apps, schema_editor):
    """Unifica alias conocidos (gr -> g, lt -> l...). Valores propios como pack/caja se respetan."""
    Producto = apps.get_model('products', 'Producto')
    for producto in Producto.objects.all():
        actual = (producto.unidad_medida or '').strip()
        valor = ALIAS_UNIDADES.get(actual.lower(), actual or 'unidad')
        if producto.unidad_medida != valor:
            producto.unidad_medida = valor
            producto.save(update_fields=['unidad_medida'])


def marcar_viandas(apps, schema_editor):
    """Los productos de la categoría 'Vianda' pasan a ser viandas: sin costo de compra ni stock."""
    Producto = apps.get_model('products', 'Producto')
    Producto.objects.filter(categoria__nombre__iexact='vianda').update(
        es_vianda=True, es_fabricable=False, costo_compra=0, dias_caducidad=None,
        tipo_conservacion='ambiente', unidad_medida='unidad',
    )


